import React, { useState } from "react";
import { CircularProgressbar, buildStyles } from "react-circular-progressbar";
import "react-circular-progressbar/dist/styles.css";
import '../Main/Welcome.css';

const Ahorro = () => {
  const [metaAhorro, setMetaAhorro] = useState(1000); // Meta de ahorro
  const [ahorroActual, setAhorroActual] = useState(0); // Cantidad de ahorro actual
  const [abono, setAbono] = useState(0); // Cantidad de abono

  // Función para manejar el cambio en el input de abono
  const handleAbonoChange = (e) => {
    setAbono(parseFloat(e.target.value));
  };

  // Función para abonar al ahorro
  const handleAbonar = () => {
    setAhorroActual((prevAhorro) => {
      const nuevoAhorro = prevAhorro + abono;
      return nuevoAhorro > metaAhorro ? metaAhorro : nuevoAhorro;
    });
    setAbono(0); // Resetea el input de abono
  };

  // Calcular el porcentaje de progreso
  const porcentajeProgreso = (ahorroActual / metaAhorro) * 100;

  return (
    <div>
      <h2>Meta de Ahorro: ${metaAhorro}</h2>
      <h3>Ahorro Actual: ${ahorroActual}</h3>

      {/* Círculo de progreso */}
      <div style={{ width: 150, height: 150, margin: "20px auto" }}>
        <CircularProgressbar
          value={porcentajeProgreso}
          text={`${Math.round(porcentajeProgreso)}%`}
          styles={buildStyles({
            textColor: "#000",
            pathColor: "#3b82f6",
            trailColor: "#d6d6d6",
          })}
        />
      </div>

      {/* Input para abonar */}
      <input
        type="number"
        value={abono}
        onChange={handleAbonoChange}
        placeholder="Cantidad a abonar"
      />
      <button onClick={handleAbonar}>Abonar</button>
    </div>
  );
};

export default Ahorro;


//npm install react-circular-progressbar
